<body>

    <header>
        <div class="logo">🍔 DeliveryExpress</div>
        <div style="font-size: 0.9rem;">Acompanhe seu pedido</div>
    </header>

    <div class="container">
        <h2>Nossos Pratos</h2>
        <ul class="product-list" id="productList">
            <!-- Os produtos serão inseridos aqui via JavaScript -->
        </ul>
    </div>

    <!-- Botão Flutuante da Sacola -->
    <div class="floating-cart" onclick="toggleCart()">
        <span>🛒</span>
        <span id="cartText">Sacola</span>
        <span class="cart-count" id="cartCount">0</span>
    </div>

    <!-- Modal da Sacola -->
    <div class="cart-modal" id="cartModal">
        <div class="cart-content">
            <span class="close-cart" onclick="toggleCart()">&times;</span>
            <h2>Sua Sacola</h2>
            <div id="cartItemsContainer">
                <p class="empty-msg">Sua sacola está vazia.</p>
            </div>
            <div class="total-price">Total: R$ <span id="cartTotal">0,00</span></div>
            <button class="checkout-btn" onclick="alert('Pedido enviado para cozinha!')">Finalizar Pedido</button>
        </div>
    </div>

    <script>
        // Dados dos Produtos
        const products = [
            { id: 1, name: "X-Bacon Supremo", price: 25.90, desc: "Pão brioche, carne moída, bacon crocante e queijo derretido.", img: "https://via.placeholder.com/60?text=Burger" },
            { id: 2, name: "Pizza Calabresa", price: 45.00, desc: "Massa fina, molho tomate, calabresa fatiada e orégano.", img: "https://via.placeholder.com/60?text=Pizza" },
            { id: 3, name: "Refrigerante Lata", price: 5.00, desc: "Coca-Cola, Guaraná ou Sprite gelado.", img: "https://via.placeholder.com/60?text=Refri" },
            { id: 4, name: "Batata Frita Grande", price: 18.50, desc: "Porção generosa de batatas fritas temperadas.", img: "https://via.placeholder.com/60?text=Fritas" },
            { id: 5, name: "Milkshake de Morango", price: 12.00, desc: "Sorvete de morango cremoso com calda caseira.", img: "https://via.placeholder.com/60?text=Milkshake" }
        ];

        let cart = [];

        // Inicializa a página carregando os produtos
        document.addEventListener('DOMContentLoaded', () => {
            renderProducts();
        });

        function renderProducts() {
            const productList = document.getElementById('productList');
            productList.innerHTML = '';

            products.forEach(product => {
                const li = document.createElement('li');
                li.className = 'product-item';
                li.innerHTML = `
                    <div class="product-info">
                        <img src="${product.img}" alt="${product.name}" class="product-img">
                        <div class="product-details">
                            <h3>${product.name}</h3>
                            <p>R$ ${product.price.toFixed(2).replace('.', ',')}</p>
                        </div>
                    </div>
                    <button class="add-btn" onclick="addToCart(${product.id})">Adicionar</button>
                `;
                productList.appendChild(li);
            });
        }

        function addToCart(productId) {
            const product = products.find(p => p.id === productId);

            // Verifica se já existe no carrinho
            const existingItem = cart.find(item => item.id === productId);

            if (existingItem) {
                existingItem.quantity += 1;
            } else {
                cart.push({ ...product, quantity: 1 });
            }

            updateCartUI();

            // Efeito visual simples (opcional)
            alert(`${product.name} adicionado à sacola!`);
        }

        function removeFromCart(productId) {
            cart = cart.filter(item => item.id !== productId);
            updateCartUI();
        }

        function updateCartUI() {
            // Atualiza contador do botão flutuante
            const totalCount = cart.reduce((sum, item) => sum + item.quantity, 0);
            document.getElementById('cartCount').innerText = totalCount;

            // Atualiza conteúdo do modal
            const cartItemsContainer = document.getElementById('cartItemsContainer');
            const cartTotalElement = document.getElementById('cartTotal');

            if (cart.length === 0) {
                cartItemsContainer.innerHTML = '<p class="empty-msg">Sua sacola está vazia.</p>';
                cartTotalElement.innerText = '0,00';
            } else {
                cartItemsContainer.innerHTML = '';
                let total = 0;

                cart.forEach(item => {
                    const itemTotal = item.price * item.quantity;
                    total += itemTotal;

                    const div = document.createElement('div');
                    div.className = 'cart-item';
                    div.innerHTML = `
                        <div>
                            <strong>${item.name}</strong><br>
                            <small>${item.quantity}x R$ ${item.price.toFixed(2).replace('.', ',')}</small>
                        </div>
                        <div>
                            <span style="margin-right: 10px;">R$ ${itemTotal.toFixed(2).replace('.', ',')}</span>
                            <span style="color: red; cursor: pointer;" onclick="removeFromCart(${item.id})">🗑️</span>
                        </div>
                    `;
                    cartItemsContainer.appendChild(div);
                });

                cartTotalElement.innerText = total.toFixed(2).replace('.', ',');
            }
        }

        function toggleCart() {
            const modal = document.getElementById('cartModal');
            if (modal.style.display === 'flex') {
                modal.style.display = 'none';
            } else {
                modal.style.display = 'flex';
            }
        }
    </script>
</body>
</html>
